// Merge the calendar row with the text the model returned.
const salida = [];
const filas = $('Filtrar piezas de hoy').all();
for (const [i, item] of $input.all().entries()) {
  const fila = (filas[i] || filas[0]).json;
  const texto = (item.json?.content?.[0]?.text || '').trim();
  salida.push({
    json: {
      ...fila,
      texto,
      estado: texto ? 'revisar_marca' : 'descartada',
      motivo_rechazo: texto ? '' : 'el modelo no devolvio texto',
    },
  });
}
return salida;

