// Read the filter's verdict without trusting it came out clean.
const salida = [];
const piezas = $('Montar la pieza').all();
for (const [i, item] of $input.all().entries()) {
  const pieza = (piezas[i] || piezas[0]).json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let veredicto;
  try {
    veredicto = JSON.parse(bruto);
  } catch (error) {
    veredicto = { apta: false, motivos: ['veredicto no parseable: ' + bruto.slice(0, 150)], gravedad: 'grave' };
  }
  salida.push({
    json: {
      ...pieza,
      apta: veredicto.apta === true,
      motivo_rechazo: (veredicto.motivos || []).join('; '),
      gravedad: veredicto.gravedad || 'grave',
    },
  });
}
return salida;

